impl markup::Transform for super::AnyElementContent {
    fn transform(&self, ctx: &mut dyn markup::Context) -> Self {
        let node = markup::ask(ctx.drawing(), super::Context::any_element, self);
        node.unwrap_or_else(|| self.transform_children(ctx))
    }

    fn transform_children(&self, ctx: &mut dyn markup::Context) -> Self {
        if let Self::Other(node) = self {
            return Self::Other(node.transform(ctx));
        }
        transform_any_element_1(self, ctx)
            .or_else(|| transform_any_element_2(self, ctx))
            .or_else(|| transform_any_element_3(self, ctx))
            .or_else(|| transform_any_element_4(self, ctx))
            .or_else(|| transform_any_element_5(self, ctx))
            .or_else(|| transform_any_element_6(self, ctx))
            .or_else(|| transform_any_element_7(self, ctx))
            .or_else(|| transform_any_element_8(self, ctx))
            .or_else(|| transform_any_element_9(self, ctx))
            .unwrap_or_else(|| self.clone())
    }
}

impl markup::Visit for super::AnyElementContent {
    fn visit(&self, visitor: &mut dyn markup::Visitor) {
        let next = markup::show(visitor.drawing(), super::Visitor::any_element, self);
        if next == markup::Descend::Yes {
            self.visit_children(visitor);
        }
    }

    fn visit_children(&self, visitor: &mut dyn markup::Visitor) {
        if let Self::Other(node) = self {
            node.visit(visitor);
        }
        visit_any_element_1(self, visitor);
        visit_any_element_2(self, visitor);
        visit_any_element_3(self, visitor);
        visit_any_element_4(self, visitor);
        visit_any_element_5(self, visitor);
        visit_any_element_6(self, visitor);
        visit_any_element_7(self, visitor);
        visit_any_element_8(self, visitor);
        visit_any_element_9(self, visitor);
    }
}

