impl markup::Transform for super::ColorContent {
    fn transform(&self, ctx: &mut dyn markup::Context) -> Self {
        let node = markup::ask(ctx.drawing(), super::Context::color, self);
        node.unwrap_or_else(|| self.transform_children(ctx))
    }

    fn transform_children(&self, ctx: &mut dyn markup::Context) -> Self {
        match self {
            Self::HueSaturationLuminanceColorModel(arm) => {
                Self::HueSaturationLuminanceColorModel(arm.transform(ctx))
            }
            Self::Other(node) => Self::Other(node.transform(ctx)),
            Self::PresetColor(arm) => Self::PresetColor(arm.transform(ctx)),
            Self::RGBColorModelHexVariant(arm) => Self::RGBColorModelHexVariant(arm.transform(ctx)),
            Self::RGBColorModelPercentageVariant(arm) => {
                Self::RGBColorModelPercentageVariant(arm.transform(ctx))
            }
            Self::SchemeColor(arm) => Self::SchemeColor(arm.transform(ctx)),
            Self::SystemColor(arm) => Self::SystemColor(arm.transform(ctx)),
        }
    }
}

